python - <<'PY'
import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(timeout=30);o=r.get_obs(cameras=(),video='none');p=o.meta['proprio']['now'];print('base',p[28:35]);print('eefL',p[35:42]);print('eefR',p[42:49]);
for k,v in o.meta['cameras'].items():
 if 'realsense' in k:
  c=np.array(v['cam2world_gl']);print(k.split(':')[1], 'p',np.round(c[:3,3],2),'gaze',np.round(-c[:3,2],2))
PY

